// Normalizacja tekstu pod odsłuch po polsku (skróty, symbole, URL-e).
function prepareForSpeech(text) {
  let s = String(text || '');
  s = s.replace(/https?:\/\/[^\s,;)]+/g, '').replace(/\s+([,.;:])/g, '$1'); // linki nie są czytane
  s = s.replace(/[*_#`>|]/g, '');                     // markdown
  s = s.replace(/\s*[–—]\s*/g, ' – ');
  s = s.replace(/(\d)\s?%/g, '$1 procent');
  s = s.replace(/\$\s?(\d[\d.,]*)\s?(mld|mln|tys\.)?/g, (m, n, u) => `${n}${u ? ' ' + u : ''} dolarów`);
  s = s.replace(/€\s?(\d[\d.,]*)/g, '$1 euro');
  s = s.replace(/\bnp\./g, 'na przykład').replace(/\bm\.in\./g, 'między innymi').replace(/\btzw\./g, 'tak zwany');
  s = s.replace(/\bitd\./g, 'i tak dalej').replace(/\bok\.\s(?=\d)/g, 'około ');
  s = s.replace(/\bAI\b/g, 'AI').replace(/\bvs\.?\b/g, 'kontra');
  s = s.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  return s;
}

// Dzieli tekst na fragmenty <= maxChars, wyłącznie na granicach zdań/akapitów.
function chunkText(text, maxChars) {
  maxChars = maxChars || 2500;
  const paragraphs = String(text || '').split(/\n{2,}/).map((p) => p.trim()).filter(Boolean);
  const chunks = [];
  let cur = '';
  const push = () => { if (cur.trim()) chunks.push(cur.trim()); cur = ''; };
  for (const p of paragraphs) {
    if ((cur + '\n\n' + p).length <= maxChars) { cur = cur ? cur + '\n\n' + p : p; continue; }
    push();
    if (p.length <= maxChars) { cur = p; continue; }
    const sentences = p.match(/[^.!?…]+[.!?…]+["”»)]*\s*|[^.!?…]+$/g) || [p];
    for (const s of sentences) {
      if ((cur + s).length > maxChars) push();
      if (s.length > maxChars) { for (let i = 0; i < s.length; i += maxChars) chunks.push(s.slice(i, i + maxChars).trim()); continue; }
      cur += s;
    }
  }
  push();
  return chunks;
}

// Bitrate z formatu ElevenLabs, np. "mp3_44100_96" -> 96
function bitrateFromFormat(fmt) {
  const m = String(fmt || '').match(/^mp3_\d+_(\d+)$/);
  return m ? parseInt(m[1], 10) : 128;
}

// Czas trwania MP3 CBR na podstawie rozmiaru
function mp3DurationSeconds(bytes, kbps) {
  return Math.round((bytes * 8) / (kbps * 1000) * 100) / 100;
}

// Usuwa nagłówek ID3v2 (przy sklejaniu fragmentów zostawiamy tylko pierwszy)
function stripId3(buf) {
  if (buf.length > 10 && buf[0] === 0x49 && buf[1] === 0x44 && buf[2] === 0x33) {
    const size = ((buf[6] & 0x7f) << 21) | ((buf[7] & 0x7f) << 14) | ((buf[8] & 0x7f) << 7) | (buf[9] & 0x7f);
    return buf.subarray(10 + size);
  }
  return buf;
}

// Rozdziały z czasami startu
function buildChapters(parts) {
  let t = 0;
  return parts.map((p, i) => {
    const ch = { index: i, title: p.title, start_seconds: Math.round(t * 100) / 100, duration_seconds: p.duration_seconds, audio_asset_id: p.audio_asset_id || null, story_ids: p.story_ids || [] };
    t += p.duration_seconds;
    return ch;
  });
}
// ---- /lib/tts.cjs ----
const cfg = $('Load config').first().json;
const el = cfg.elevenlabs || {};
const b = $('Get briefing').first().json;
const budget = $('Budget gate').first().json.budget;
if (!el.voice_id || /^REPLACE/.test(el.voice_id)) throw new Error('Ustaw app_config.elevenlabs.voice_id (polski głos z ElevenLabs Voice Library)');
if (!b.script || !Array.isArray(b.script.chapters) || !b.script.chapters.length) throw new Error('Briefing nie ma scenariusza audio');

const items = [];
b.script.chapters.forEach((ch, ci) => {
  const text = prepareForSpeech(ch.text);
  chunkText(text, el.max_chunk_chars || 2500).forEach((chunk, k) => {
    items.push({ briefing_id: b.id, briefing_date: b.briefing_date, chapter_index: ci, chunk_index: k,
      chapter_title: ch.title, chapter_kind: ch.kind, story_ids: ch.story_ids || [], text: chunk });
  });
});
const totalChars = items.reduce((a, it) => a + it.text.length, 0);
const monthlyLimit = budget.limits && budget.limits.monthly_characters;
if (monthlyLimit && Number(budget.month_characters) + totalChars > monthlyLimit) {
  throw new Error(`Przekroczony miesięczny limit znaków ElevenLabs (${budget.month_characters} + ${totalChars} > ${monthlyLimit})`);
}
const modelId = el.model_id || 'eleven_multilingual_v2';
return items.map((it, i) => {
  const body = { text: it.text, model_id: modelId, voice_settings: el.voice_settings || {} };
  if (i > 0 && items[i - 1].chapter_index === it.chapter_index) body.previous_text = items[i - 1].text.slice(-400);
  if (i < items.length - 1 && items[i + 1].chapter_index === it.chapter_index) body.next_text = items[i + 1].text.slice(0, 400);
  if (/flash|turbo|v3/.test(modelId)) body.language_code = 'pl';
  return { json: { ...it, voice_id: el.voice_id, output_format: el.output_format || 'mp3_44100_96', total_characters: totalChars, body } };
});

